import pathlib,json,hashlib,datetime,collections,sys
import xlrd
base=pathlib.Path('data/evidence/contracts/leafy-greens');xls=base/'retrieval/dearing2025-nz-organic-nonorganic-vegetables-cyclone-data-alternate.xls';w=xlrd.open_workbook(str(xls));s=w.sheet_by_name('Data');header=s.row_values(0);assert s.nrows==154 and s.ncols==19
source='dearing2025-nz-organic-nonorganic-vegetables-cyclone';xls_sha=hashlib.sha256(xls.read_bytes()).hexdigest();allowed={'lettuce','silverbeet','bok choi','cabbage red','cabbage','leek','celery','kale','spring onion','parsley','chard','chinese water spinach'}
raw=[];records=[];excluded=[]
for n in range(1,s.nrows):
 r=dict(zip(header,s.row_values(n)));raw.append(r);leaf=r['Vegetable'].strip().lower();sample=str(int(r['Sample ID']));
 if leaf not in allowed:
  excluded.append({'sheet_row':n+1,'sample_id':sample,'vegetable':r['Vegetable'],'decision':'out_of_leaf_food_scope','reason':'Root, bulb, fruit, pod or inflorescence vegetable; no edible leaf fraction reported. Genus-level summaries mixing these with leaves cannot become leaf concentrations.'});continue
 for c in range(10,17):
  a=header[c];v=r[a];code={'As':'tAs','Hg':'tHg'}.get(a,a);assert isinstance(v,(float,int)) and v>=0
  records.append({'id':f'lg-full-dearing-{sample}-{code}','source_id':source,'family_id':'dearing-hawkes-bay-2024','analyte':code,'material':r['Vegetable'],'species':'Genus '+r['Genus']+'; exact species not supplied in per-sample workbook','form':'fresh edible parts, running-tap-water washed and excess water removed; source composite','basis':'Fresh weight; individually measured fresh weights before drying to constant mass','statistic':'per-composite reported concentration, potentially half-LOD substituted','reported_value':v,'value':None,'lower_bound':0,'upper_bound':.01 if a=='Hg' else 2*v,'bound_basis':'All Hg explicitly below0.01mg/kg in primary Results. For other metals, per-sample detected/half-LOD flags and limits are absent: union of an exact reported measurement v and a half-LOD code v has conservative outer bounds[0,2v]. These are reporting-identification bounds, not confidence intervals; no zero measurement or half-LOD point is imputed.','n':1,'n_note':'One representative composite per workbook row; underlying vegetables pooled by market and type.736 individuals formed153 composites overall; per-row sub-sample N unreported.','sample_unit':'representative composite from one vegetable type and market','origin_or_market':'Hawke’s Bay, New Zealand; growing-location code '+str(int(r['Grown Location']))+'; '+r['Market Garden'],'year':'February2024, one year after Cyclone Gabrielle','organic':r['Organic Text'],'flooded':r['Flooded Text'],'unit':'mg/kg fresh weight','censoring':'Measured versus half-LOD status unresolved per record; all mercury non-detects. Original spreadsheet values retained separately.','locator':{'artifact':str(xls),'sha256':xls_sha,'kind':'cell','location':f'Data!{xlrd.formula.colname(c)}{n+1}; Sample ID={sample}; {r["Vegetable"]}; {a}'}})
assert len(raw)==153 and len({r['Sample ID'] for r in raw})==153;assert len(records)==455
raw_out={'source':source,'dataset_doi':'10.5281/zenodo.15540807','artifact':str(xls),'sha256':xls_sha,'sheet':'Data','rows':raw};(base/'dearing-workbook-raw.json').write_text(json.dumps(raw_out,indent=2)+'\n')
(base/'recovered-dearing-results.json').write_text(json.dumps({'status':'Raw leaf composite facts recovered; published subgroup summary extraction still requires reconciliation','records':records,'other_vegetable_dispositions':excluded},indent=2)+'\n')
review={'source_id':source,'reviewed_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'paper_identity_verified':True,'paper_completeness_verified':True,'dataset_identity_verified':True,'dataset_completeness_verified':True,'identity_proof':'Recovered primary PDF title, Dearing/Ye/Robertshaw authors and DOI10.12688/f1000research.175538.1 match.23-page file includes original research and four public peer reviews. Primary Data availability links Zenodo15540807; repository title, workbook author,153 data rows, seven analytes and metadata columns agree. Workbook is read-only; all153 rows and19 columns preserved.','read_locations':['Research Methods pp3–5','Concentration Tables2–3 pp5–6','Sensitivity Table6 p8','Data availability p9','Dataset Data!A1:S154'],'extraction_complete':False,'reason':'455 per-composite leaf-associated records from65 composites recovered. Source-specific genus medians/maxima and any numeric figure summaries still require reconciliation; all other library records remain in progress.','censoring_issue':'The workbook stores source half-LOD substitutions without per-sample detection flags/LOD. The paper says all Hg<0.01mg/kg while workbook Hg=.0025 for all153 rows. Do not call these measured .0025 values; preserve conservative bounds and the discrepancy.','leaf_composites':65,'leaf_concentration_records':455,'nonleaf_composites':88,'other_elements':'logCD and LogN are model transformations, not additional metal measurements.','causal_limit':'Cross-sectional organic/flood associations; no before/after intervention or demonstrated remediation effect.'};(base/'primary-review-dearing.json').write_text(json.dumps(review,indent=2)+'\n');print('Read-only workbook verified:153 composites;65 leaf-associated;455 concentration records; published summaries not yet reconciled')
